arguments.file_text:
namespace sv_78c0c69b9e004836ba48caebfc6a6c2e.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_78c0c69b9e004836ba48caebfc6a6c2e.Services

<div class="channel-list">
    <h5 class="channel-list-header">Channels</h5>

    @foreach (var channel in Channels)
    {
        <button class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
            <div class="channel-name-row">
                <span class="channel-name"># @channel.Name</span>
                @if (channel.UnreadCount > 0)
                {
                    <span class="unread-badge">@channel.UnreadCount</span>
                }
            </div>
            @if (!string.IsNullOrWhiteSpace(channel.Description))
            {
                <span class="channel-desc">@Truncate(channel.Description, 40)</span>
            }
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2c2f33;
    color: #dcddde;
    overflow-y: auto;
}

.channel-list-header {
    padding: 1rem 0.75rem 0.5rem;
    margin: 0;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    border: none;
    background: none;
    padding: 0.45rem 0.75rem;
    color: #8e9297;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.35rem;
    max-width: calc(100% - 0.7rem);
    transition: background-color 0.12s, color 0.12s;
}

.channel-item:hover {
    background: #34373c;
    color: #dcddde;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-name-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 500;
    font-size: 0.9rem;
}

.unread-badge {
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 9px;
    min-width: 1.1rem;
    text-align: center;
}

.channel-desc {
    display: block;
    font-size: 0.75rem;
    color: #72767d;
    margin-top: 0.1rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

@using sv_78c0c69b9e004836ba48caebfc6a6c2e.Services

<div class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="btn-close btn-close-sm" @onclick="OnClose" aria-label="Close thread"></button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <span class="quote-author">@RootMessage.Author</span>
            <p class="quote-content">@RootMessage.Content</p>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSubmit="OnSendReply" />
    }
</div>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    border-left: 1px solid #dee2e6;
    background: #fff;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

.thread-header h6 {
    margin: 0;
    font-weight: 600;
}

.btn-close-sm {
    font-size: 0.65rem;
}

.thread-root-quote {
    padding: 0.65rem 0.75rem;
    margin: 0.5rem 0.75rem;
    background: #f8f9fa;
    border-left: 3px solid #6c757d;
    border-radius: 0 4px 4px 0;
}

.quote-author {
    font-weight: 600;
    font-size: 0.85rem;
}

