@using sv_78c0c69b9e004836ba48caebfc6a6c2e.Services

<div class="channel-list">
    <h5 class="channel-list-header">Channels</h5>

    @foreach (var channel in Channels)
    {
        <button class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
            <div class="channel-name-row">
                <span class="channel-name"># @channel.Name</span>
                @if (channel.UnreadCount > 0)
                {
                    <span class="unread-badge">@channel.UnreadCount</span>
                }
            </div>
            @if (!string.IsNullOrWhiteSpace(channel.Description))
            {
                <span class="channel-desc">@Truncate(channel.Description, 40)</span>
            }
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #2c2f33;
    color: #dcddde;
    overflow-y: auto;
}

.channel-list-header {
    padding: 1rem 0.75rem 0.5rem;
    margin: 0;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    border: none;
    background: none;
    padding: 0.45rem 0.75rem;
    color: #8e9297;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.35rem;
    max-width: calc(100% - 0.7rem);
    transition: background-color 0.12s, color 0.12s;
}

.channel-item:hover {
    background: #34373c;
    color: #dcddde;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-name-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 500;
    font-size: 0.9rem;
}

.unread-badge {
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 9px;
    min-width: 1.1rem;
    text-align: center;
}

.channel-desc {
    display: block;
    font-size: 0.75rem;
    color: #72767d;
    margin-top: 0.1rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

