@using sv_78c0c69b9e004836ba48caebfc6a6c2e.Services

<div class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="btn-close btn-close-sm" @onclick="OnClose" aria-label="Close thread"></button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <span class="quote-author">@RootMessage.Author</span>
            <p class="quote-content">@RootMessage.Content</p>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSubmit="OnSendReply" />
    }
</div>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    border-left: 1px solid #dee2e6;
    background: #fff;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

.thread-header h6 {
    margin: 0;
    font-weight: 600;
}

.btn-close-sm {
    font-size: 0.65rem;
}

.thread-root-quote {
    padding: 0.65rem 0.75rem;
    margin: 0.5rem 0.75rem;
    background: #f8f9fa;
    border-left: 3px solid #6c757d;
    border-radius: 0 4px 4px 0;
}

.quote-author {
    font-weight: 600;
    font-size: 0.85rem;
}

.quote-content {
    margin: 0.2rem 0 0;
    font-size: 0.85rem;
    color: #495057;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
}

