@using sv_78c0c69b9e004836ba48caebfc6a6c2e.Services

<div class="message-area">
    <div class="message-area-header">
        @if (Channel is not null)
        {
            <h5># @Channel.Name</h5>
            <span class="channel-description">@Channel.Description</span>
        }
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
        @if (IsLoadingMore)
        {
            <div class="loading-more">Loading older messages…</div>
        }

        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         IsThreadStarter="@(msg.ReplyToId is null && ThreadCounts.ContainsKey(msg.Id))"
                         ReplyCount="@(ThreadCounts.GetValueOrDefault(msg.Id))"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel?.Name ?? "channel"}…")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    private ElementReference messageListRef;

    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private async Task HandleScroll()
    {
        // Fire load-more when scrolled near the top
        await OnLoadMore.InvokeAsync();
    }
}

