arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_78c0c69b9e004836ba48caebfc6a6c2e.Services
@using sv_78c0c69b9e004836ba48caebfc6a6c2e.Components.Chat
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     SelectedChannelId="selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(threadRootMessage is null ? "full-width" : "")">
        <MessageArea Channel="selectedChannel"
                     Messages="messages"
                     ThreadCounts="threadCounts"
                     IsLoadingMore="isLoadingMore"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnLoadMore="LoadOlderMessages" />
    </div>

    @if (threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, int> threadCounts = new();
    private int? selectedChannelId;
    private Channel? selectedChannel;
    private bool isLoadingMore;
    private bool hasMoreMessages = true;

    // Thread state
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    // Scroll-to-top detection
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<Chat>? selfRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            selfRef = DotNetObjectReference.Create(this);
            jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-78c0c69b9e004836ba48caebfc6a6c2e/Components/Pages/Chat.razor.js");
            await jsModule.InvokeVoidAsync("initScrollWatcher", ".message-list", selfRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        await LoadOlderMessages();
        await InvokeAsync(StateHasChanged);
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        hasMoreMessages = true;
        threadRootMessage = null;
        threadReplies = [];

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        hasMoreMessages = messages.Count >= PageSize;
        await BuildThreadCounts();
        _ = ChatService.MarkChannelReadAsync(channelId);
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore || !hasMoreMessages || selectedChannelId is null) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, messages.Count, PageSize);
        hasMoreMessages = older.Count >= PageSize;

        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            await BuildThreadCounts();
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannelId is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread count in main view
        threadCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId)
               ?? threadReplies.FirstOrDefault(m => m.Id == args.MessageId);

        if (msg is null) return;

        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
        if (existing is not null)
        {
            if (!existing.Users.Contains("You"))
                existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
        }
    }

    private Task BuildThreadCounts()
    {
        threadCounts.Clear();
        // Messages that are replies reference a ReplyToId;
        // group them to build counts for root messages
        foreach (var group in messages.Where(m => m.ReplyToId is not null).GroupBy(m => m.ReplyToId!.Value))
        {
            threadCounts[group.Key] = group.Count();
        }
        return Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        if (jsModule is not null)
        {
            try
            {
                await jsModule.InvokeVoidAsync("dispose");
                await jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
        selfRef?.Dispose();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 180px;
    flex-shrink: 0;
}

.chat-main {
    width: 55%;
    flex-grow: 1;
    min-width: 0;
    transition: width 0.2s ease;
}

.chat-main.full-width {
    width: 80%;
}

.chat-thread {
    width: 25%;
    min-width: 250px;
    flex-shrink: 0;
}

let scrollElement = null;
let dotnetRef = null;
let scrollHandler = null;

export function initScrollWatcher(selector, ref) {
    dotnetRef = ref;
    scrollElement = document.querySelector(selector);
    if (!scrollElement) return;

    scrollHandler = () => {
        if (scrollElement.scrollTop <= 10) {
            dotnetRef.invokeMethodAsync('OnScrolledToTop');
        }
    };
    scrollElement.addEventListener('scroll', scrollHandler, { passive: true });
}

export function dispose() {
    if (scrollElement && scrollHandler) {
        scrollElement.removeEventListener('scroll', scrollHandler);
    }
    scrollElement = null;
    dotnetRef = null;
    scrollHandler = null;
}

